#include "smartlieducation.h"
#include "sensors.h"
#include "emg.h"
#include "finger.h"
#include "smartli.h"

#define LED_PIN 25

// ПЕРЕМЕННЫЕ

uint8_t speed = 100; // ЗНАЧЕНИЕ СКОРОСТИ ПО УМОЛЧАНИЮ
uint8_t dtime = 500; // ЗНАЧЕНИЕ ВРЕМЕНИ ДВИЖЕНИЯ ПАЛЬЦЕВ

uint8_t rot1 = 0;
uint8_t rot2 = 0;
uint8_t rot3 = 0;
uint8_t rot4 = 0;
uint8_t rot5 = 0;

uint8_t fingerState1 = 0; // 0 - 0 градусов, 1 - 90 градусов, 2 - 45 градусов
uint8_t fingerState2 = 0; // 0 - 0 градусов, 1 - 90 градусов, 2 - 45 градусов
uint8_t fingerState3 = 0; // 0 - 0 градусов, 1 - 90 градусов, 2 - 45 градусов
uint8_t fingerState4 = 0; // 0 - 0 градусов, 1 - 90 градусов, 2 - 45 градусов
uint8_t fingerState5 = 0; // 0 - 0 градусов, 1 - 90 градусов, 2 - 45 градусов


//кнопка
uint8_t reading = 0;
uint8_t buttonMode = 0;
uint8_t pressCount = 0;
uint8_t buttonPressedTime = 0;

//емг
uint8_t emg1 = 0;
uint8_t emg2 = 0;
uint8_t lastEmg1 = 0;
uint8_t lastEmg2 = 0;
uint8_t emgChange = 0;
uint8_t emgCheck = 0;
uint8_t block = 0;

// ===============================================
//   РЕЖИМ ИНТЕРАКТИВНОЙ НАСТРОЙКИ ПО UART
// ===============================================

bool interactiveMode = false;
unsigned long lastBlinkTime = 0;
bool ledState = false;

uint8_t gripTemplate = 0; // шаблон (0 или 1)

// [шаблон][палец]
uint8_t fingerAngles[2][5] = {
  {45, 45, 45, 45, 45},
  {90, 90, 90, 90, 90}
};

uint8_t fingerSpeeds[2][5] = {
  {60, 60, 60, 60, 60},
  {100, 100, 100, 100, 100}
};


void setup() {
  Serial.begin(9600);
  delay(2000);//ЗАДЕРЖКА ДЛЯ СТАБИЛИЗАЦИИ ПИТАНИЯ
  WDT_Init();

  EMG1.SetCoeffs(100, 800);
  EMG2.SetCoeffs(100, 800);

  pinMode(LED_PIN, OUTPUT);

  fingersTets(); //ТЕСТ ПАЛЬЦЕВ

}

void loop() {
  WDT_Tick();

  checkSerialCommand();

  if (interactiveMode) {
    unsigned long currentMillis = millis();
    if (currentMillis - lastBlinkTime >= 1000) {
      lastBlinkTime = currentMillis;
      ledState = !ledState;
      digitalWrite(LED_PIN, ledState);
    }
    return; // в режиме настройки обычная работа не выполняется
  }

  //КНОПКА

  reading = Smartli.SwitchState();delay(100); // читаем состояние кнопки
  buttonPressedTime = Smartli.SwitchPressedTime(2);delay(100); // читаем длительность нажатия

  // ЕСЛИ НАЖАТИЕ КНОПКИ БОЛЬШЕ 2Х СЕКУНД И СОСТОЯНИЕ КНОПКИ = 1
  if (buttonPressedTime > 2000 && reading == 1){
    // ЕСЛИ РЕЖИМ = 3 -> СБРАСЫВАЕМ РЕЖИМ 
    if (buttonMode == 3){buttonMode = 0;}
    //УВЕЛИЧИВАЕМ ЗНАЧЕНИЕ РЕЖИМА -> ИНДИКАЦИЯ РЕЖИМА -> ВИБРО СИГНАЛ ПЕРЕКЛЮЧЕНИЯ 
     buttonMode++;led(buttonMode);vibro();
  // ИНАЧЕ ЕСЛИ ВРЕМЯ НАЖАТИЯ ОТ 500 ДО 1СЕК И СОСТОЯНИЕ КНОПКИ = 1 
  }else if (buttonPressedTime > 500 && buttonPressedTime < 1000 && reading == 1){
    // УВЕЛИЧИВАЕМ ЗНАЧЕНИЕ СЧЕТЧИКА
    pressCount++;
    //ЕСЛИ СЧЕТЧИК = 3 - АВАРИЙНОЕ РАСКРЫТИЕ, АВАРИЙНАЯ ИНДИКАЦИЯ, СБРАСЫВАЕМ СЧЕТЧИК 
    if (pressCount == 3){EMERGENCY();ledAlarm();pressCount = 0;}
  }

  led(buttonMode);// ВЫВОДИМ ИНДИКАЦИЮ РЕЖИМА КНОПКИ ДЛЯ ПОСТОЯННОЙ ВИДИМОСТИ РЕЖИМА

  Serial.print("ROT1 = ");Serial.print(rot1); // ВЫВОДИМ ПОЛОЖЕНИЕ УГЛОВ ДАТЧИКОВ 
  Serial.print("  ROT2 = ");Serial.print(rot2);
  Serial.print("  ROT3 = ");Serial.print(rot3);
  Serial.print("  ROT4 = ");Serial.print(rot4);
  Serial.print("  ROT5 = ");Serial.println(rot5);
  delay(300);

  // ЕМГ
  // ЗНАЧЕНИЯ ЕМГ ПРИВОДИМ К - 1 И 0
  if(EMG1.GetRaw() > 500){emg1 = 1; emgCheck = 1;}else if (EMG1.GetRaw() < 500){emg1 = 0;}
  if(EMG2.GetRaw() > 500){emg2 = 1; emgCheck = 1;}else if (EMG2.GetRaw() < 500){emg2 = 0;}
  // ЕСЛИ ПОСЛЕДНЕЕ ЗНАЧЕНИЕ НЕ РАВНО ПРЕДЫДУЩЕМУ -> ПРИРАВНИВАЕМ И МЕНЯЕМ СОСТОЯНИЕ НА 1
  if (emg1 != lastEmg1){lastEmg1 = emg1; emgChange = 1;}
  if (emg2 != lastEmg2){lastEmg2 = emg2; emgChange = 1;}
  //ЕСЛИ СОСТОЯНИЕ = 1 - ФУНКЦИЯ ВЫБОРА СХВАТОВ 
  if (emgChange == 1){gripMode();emgChange = 0;}


}

