void ledAlarm(){//АВАРИЙНАЯ ИНДИКАЦИЯ - пока счетчик = 3 светит светодиод и сбрасывает режимы(не реагирует на датчики)
if (pressCount == 3){digitalWrite(LED_PIN, HIGH);buttonMode=0;}else{digitalWrite(LED_PIN, LOW);}
}

void led(int count){//ИНДИКАЦИЯ СВЕТОДИОДОМ 
  for (int i=0; i<count; i++){
    digitalWrite(LED_PIN, HIGH);
    delay(500/count);
    digitalWrite(LED_PIN, LOW);
    delay(500/count);
  }
}

