void gripMode(){// ФУНКЦИЯ СМЕНЫ РЕЖИМОВ СХВАТА
  if (buttonMode == 1){// ПЕРЕХОД В РЕЖИМ РАБОТЫ С ОДНИМ ДАТЧИКОМ
    if (emgCheck == 1){if (emg1 == 1){powerGrip();}// ЕСЛИ 1Й ДАТЧИК АКТИВЕН - СИЛОВОЙ СХВАТ
  }else if (buttonMode == 2){// ПЕРЕХОД В РЕЖИМ РАБОТЫ С ДВУМЯ ДАТЧИКАМИ
     if (emgCheck == 1){if (emg1 == 1 && emg2 == 0 && block == 0){glassGrip();block = 1;}}// ЕСЛИ 1Й ДАТЧИК АКТИВЕН А ВТОРОЙ НЕТ И ЗАЩИТА СНЯТА - ПОЛУОТКРЫТЫЙ СХВАТ
     if (emgCheck == 1){if (emg1 == 0 && emg2 == 1 && block == 0){closedPincetGrip();block = 1;}}// ЕСЛИ 1Й ДАТЧИК НЕ АКТИВЕН А ВТОРОЙ АКТИВЕН И ЗАЩИТА СНЯТА - ОТКРЫТЫЙ ПИНЦЕТНЫЙ СХВАТ
     if (emgCheck == 1){if (emg1 == 1 && emg2 == 1 && block == 0){openedPincetGrip();block = 1;}}// ЕСЛИ ОБА ДАТЧИКА АКТИВЕНЫ  И ЗАЩИТА СНЯТА - ЗАКРЫТЫЙ ПИНЦЕТНЫЙ СХВАТ
     if (emgCheck == 1){if (emg1 == 0 && emg2 == 0 ){EMERGENCY();block = 0;}}// ЕСЛИ ОБА ДАТЧИКА НЕ АКТИВНЫ - РАСКРЫТИЕ СХВАТА И СНЯТИЕ БЛОКИРОВКИ
  }else if (buttonMode == 3){// ПЕРЕХОД В РЕЖИМ СМЕНЫ СКОРОСТИ ПО ОДНОМУ ИЗ ДАТЧИКОВ
    if ((emg1 == 1 || emg2 == 1) && speed == 100){speed=60;led(speed/10);} else{speed = 100;led(speed/10);}// ЕСЛИ ОДИН ИЗ ДАТЧИКОВ АКТИВЕН - СМЕНА СКОРОСТИ И ИНДИКАЦИЯ ВЫБРАННОЙ СКОРОСТИ
  }
  }
}


