// ========== ОБРАБОТКА UART КОМАНД ==========
void checkSerialCommand() {
  if (Serial.available()) {
    String command = Serial.readStringUntil('\n');
    command.trim();

    if (command == "START_CONFIG") {
      interactiveMode = true;
      Serial.println("CONFIG_MODE_ON");
    } else if (command == "STOP_CONFIG") {
      interactiveMode = false;
      digitalWrite(LED_PIN, LOW);
      Serial.println("CONFIG_MODE_OFF");
    } else if (interactiveMode) {
      parseInteractiveCommand(command);
    }
  }
}

void parseInteractiveCommand(String cmd) {
  if (cmd.startsWith("SET_TEMPLATE")) {
    int tmpl = cmd.substring(12).toInt();
    if (tmpl >= 0 && tmpl <= 1) {
      gripTemplate = tmpl;
      Serial.print("Template set to ");
      Serial.println(tmpl);
    }
  } else if (cmd.startsWith("SET_ANGLE")) {
    int idx1 = cmd.indexOf(' ');
    int idx2 = cmd.indexOf(' ', idx1 + 1);
    int finger = cmd.substring(idx1 + 1, idx2).toInt();
    int angle = cmd.substring(idx2 + 1).toInt();

    if (finger >= 1 && finger <= 5 && angle >= 0 && angle <= 90) {
      fingerAngles[gripTemplate][finger - 1] = angle;
      Serial.print("Angle for finger "); Serial.print(finger);
      Serial.print(" in template "); Serial.print(gripTemplate);
      Serial.print(" set to "); Serial.println(angle);
    }
  } else if (cmd.startsWith("SET_SPEED")) {
    int idx1 = cmd.indexOf(' ');
    int idx2 = cmd.indexOf(' ', idx1 + 1);
    int finger = cmd.substring(idx1 + 1, idx2).toInt();
    int spd = cmd.substring(idx2 + 1).toInt();

    if (finger >= 1 && finger <= 5 && spd >= 10 && spd <= 150) {
      fingerSpeeds[gripTemplate][finger - 1] = spd;
      Serial.print("Speed for finger "); Serial.print(finger);
      Serial.print(" in template "); Serial.print(gripTemplate);
      Serial.print(" set to "); Serial.println(spd);
    }
  } else if (cmd == "APPLY_TEMPLATE") {
    applyCurrentGripTemplate();
  }
}

// ========== ПРИМЕНЕНИЕ ТЕКУЩЕГО ШАБЛОНА ==========
void applyCurrentGripTemplate() {
  for (int i = 0; i < 5; i++) {
    int currentAngle = rotToAngle(i + 1);
    int targetAngle = fingerAngles[gripTemplate][i];
    int diff = targetAngle - currentAngle;
    int direction = (diff >= 0) ? 1 : -1;
    int speed = fingerSpeeds[gripTemplate][i];

    if (diff != 0) {
      switch(i) {
        case 0: Finger1.Drive(direction * speed); break;
        case 1: Finger2.Drive(direction * speed); break;
        case 2: Finger3.Drive(direction * speed); break;
        case 3: Finger4.Drive(direction * speed); break;
        case 4: Finger5.Drive(direction * speed); break;
      }
    }
  }

  delay(dtime);
  stopAll();
  vibro();
}

// ========== ТЕКУЩИЙ УГОЛ ПАЛЬЦА ==========
int rotToAngle(int fingerNum) {
  switch (fingerNum) {
    case 1: return rot1;
    case 2: return rot2;
    case 3: return rot3;
    case 4: return rot4;
    case 5: return rot5;
  }
  return 0;
}
